'use strict';
self.onmessage=async({data})=>{let bitmap;try{const blob=new Blob([data.bytes],{type:data.mime});bitmap=await createImageBitmap(blob);const scale=Math.min(1,480/Math.max(bitmap.width,bitmap.height)),canvas=new OffscreenCanvas(Math.max(1,Math.round(bitmap.width*scale)),Math.max(1,Math.round(bitmap.height*scale)));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();bitmap=null;const mime=data.mime==='image/png'?'image/png':'image/jpeg',out=await canvas.convertToBlob({type:mime,quality:0.8}),bytes=new Uint8Array(await out.arrayBuffer());canvas.width=canvas.height=1;self.postMessage({id:data.id,result:{mime,bytes}},[bytes.buffer]);}catch{self.postMessage({id:data.id,result:null});}finally{bitmap?.close();}};
